import { useState, type FormEvent } from 'react';
import {
  JxInput,
  JxSelect,
  JxSwitch,
  JxButton,
  JxAlert,
} from '@jinx-ui/react';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const ROLE_OPTIONS = [
  { label: 'Наблюдатель', value: 'viewer' },
  { label: 'Редактор', value: 'editor' },
  { label: 'Администратор', value: 'admin' },
];

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [emailTouched, setEmailTouched] = useState(false);
  const [role, setRole] = useState(ROLE_OPTIONS[0].value);
  const [notify, setNotify] = useState(true);
  const [successOpen, setSuccessOpen] = useState(false);

  const isEmailValid = EMAIL_PATTERN.test(email);
  const showEmailError = emailTouched && email.length > 0 && !isEmailValid;
  const canSubmit = isEmailValid;

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!canSubmit) return;
    setSuccessOpen(true);
  }

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-4)',
        maxWidth: '360px',
      }}
    >
      <JxAlert variant="success" open={successOpen} onOpenChange={setSuccessOpen}>
        Приглашение отправлено на {email}
      </JxAlert>

      <form
        onSubmit={handleSubmit}
        style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4)' }}
      >
        <JxInput
          label="Email"
          type="email"
          value={email}
          onValueChange={setEmail}
          onBlur={() => setEmailTouched(true)}
          hint={!showEmailError ? 'Мы отправим приглашение на этот адрес' : undefined}
          error={showEmailError ? 'Похоже, это не email-адрес' : undefined}
          placeholder="name@company.com"
        />

        <JxSelect
          label="Роль"
          value={role}
          onValueChange={setRole}
          options={ROLE_OPTIONS}
        />

        <JxSwitch
          label="Отправить уведомление"
          value={notify}
          onValueChange={setNotify}
        />

        <JxButton type="submit" variant="primary" disabled={!canSubmit}>
          Отправить приглашение
        </JxButton>
      </form>
    </div>
  );
}

